// reduce a to (-Q/2, Q/2)
int32_t freeze_32(int32_t a) {

    int32_t remainder;
    int32_t t;

    t = ((a + (1 << 22)) >> 23);
    remainder = a - (t * _Q);

    // 두번을 감산해야, |Q|/2 범위에 들어가는 경우도 발생함
    if (remainder >= (_Q / 2)) {
        remainder -= _Q;
    }
    if (remainder < -(_Q / 2)) {
        remainder += _Q;
    }

    if (remainder >= (_Q / 2)) {
        remainder -= _Q;
    }
    if (remainder < -(_Q / 2)) {
        remainder += _Q;
    }

    return remainder;
}

// we assume -Q / 2 < a < Q / 2
int32_t gethi_h(int32_t a) {

    int32_t lo, hi;

    int32_t bp_lo, bp_hi;
    int32_t a_lo, a_hi;

    // below we compute lo = a R mod^+- Q
    lo = a * RmodQ;

    bp_lo = (int32_t)(uint16_t)RmodQhi;
    bp_hi = (int32_t)(int16_t)(RmodQhi >> 16);

    a_lo = (int32_t)(uint16_t)a;
    a_hi = (int32_t)(int16_t)(a >> 16);

    hi = a_hi * bp_hi;
    hi += ((a_lo * bp_hi) >> 16);
    hi += ((a_hi * bp_lo) >> 16);

    lo -= hi * _Q;

    lo = freeze_32(lo);

    return lo * Qprime;
}

int32_t Barrett_mul_approx_h(int32_t a, int32_t b, int32_t bp, int32_t q) {

    int32_t lo, hi;

    int32_t bp_lo, bp_hi;
    int32_t a_lo, a_hi;

    lo = a * b;

    bp_lo = (int32_t)(uint16_t)bp;
    bp_hi = (int32_t)(int16_t)(bp >> 16);

    a_lo = (int32_t)(uint16_t)a;
    a_hi = (int32_t)(int16_t)(a >> 16);

    hi = a_hi * bp_hi;
    hi += ((a_lo * bp_hi) >> 16);
    hi += ((a_hi * bp_lo) >> 16);

    return lo - hi * q;
}

void ntt_barrett(int32_t a[LWE_N]) {

#if defined (_USING_C_)

    unsigned int len, start, j, k;
    int32_t zeta, zetap, t;

    k = 0;
    for (len = 128; len > 0; len >>= 1) {
        for (start = 0; start < LWE_N; start = j + len) {
            zeta = zetas_barrett2[k++];
            zetap = zetas_barrett2[k++];
            for (j = start; j < start + len; ++j) {
                t = Barrett_mul_approx_h(a[j + len], zeta, zetap, _Q);
                a[j + len] = (a[j] - t);
                a[j] = (a[j] + t);
            }
        }
    }
#else
    __asm_NTT(a, zetas_barrett2, const_buff);
#endif

}

void invntt_barrett(int32_t a[LWE_N])
{
#if defined (_USING_C_)
    unsigned int start, len, j, k;
    int32_t t, zeta, zetap;
    const int32_t f = INV256;   // 1/256 mod q
    int64_t temp = 0;
    k = 509;
    for (len = 1; len < LWE_N; len <<= 1) {
        for (start = 0; start < LWE_N; start = j + len) {
            zetap = -zetas_barrett2[k--];   // first reading approxiated twiddle factor
            zeta = -zetas_barrett2[k--];
            for (j = start; j < start + len; ++j) {
                t = a[j];
                a[j] = (t + a[j + len]);
                a[j + len] = (t - a[j + len]);
                a[j + len] = Barrett_mul_approx_h(a[j + len], zeta, zetap, _Q);
            }
        }
    }

    //==============================
    // Using KRED reduction
    //==============================
    for (j = 0; j < LWE_N; j++) {
    	a[j] = freeze_32(a[j]);
        temp = (int64_t)a[j] * f;
        a[j] = kred7340033(temp);
        a[j] = freeze_32(a[j]);
    }
#else
    __asm_iNTT(a, zetas_barrett2_ct_inv, const_buff);
    __asm_point_mul_pre(a, a, twist_table, const_buff);
#endif

}

int reduce(int a, int p)
{ // Modular reduction
  // SECURITY NOTE: TO BE USED FOR TESTING ONLY.
    a %= p;
    if (a < 0) a += p;

    return a;
}


